import{RATE,DURATION,frequency,envelope,synth,resample,analyze,random,spectrum}from'./dsp.js';
const $=id=>document.getElementById(id),canvas=$('scope'),ctx=canvas.getContext('2d');
const levels=[['First contact','A chirp in the quiet','Follow the dashed curve with a low-to-high hum or whistle. Start when the countdown ends.',0,55],['Through the static','Find it in the noise','The same chirp, with simulated noise mixed into your recording. Keep your sweep smooth.',1.5,55],['Deep space','Keep your signal clear','More noise, same mission. A sustained rising pitch matters more than volume.',3,52],['Shape matters','Every part tells a story','The χ² consistency check is now active. Keep the sound smooth across the whole sweep.',3,52],['Glitch hunter','Make a signal that belongs','The sine-Gaussian veto is active too. Finish cleanly: avoid clicks, pops, and a sharp squeak.',4,50]];
let unlocked=0;try{unlocked=Math.min(4,Math.max(0,Number(localStorage.getItem('chirplab-progress'))||0))}catch{}
let level=0,base=180,stream,ac,processor,source,mute,chunks=[],capture=false,busy=false,view=null,progress=0,raf,playing=false;
function setStatus(s){$('status').textContent=s}
function renderLevels(){ $('levels').replaceChildren(...levels.map((l,i)=>{const b=document.createElement('button');b.className='level'+(i===level?' active':'');b.disabled=i>unlocked||busy;b.setAttribute('aria-current',i===level?'step':'false');b.innerHTML=`<span class="num">${i<unlocked?'✓':String(i+1).padStart(2,'0')}</span><div><strong>${l[0]}</strong><small>${['Learn the chirp','Noise +','Noise ++','Add chisquared','Add SG veto'][i]}</small></div>`;b.onclick=()=>selectLevel(i);return b}))}
function selectLevel(i){level=i;view=null;progress=0;const l=levels[i];$('levelTag').textContent=`LEVEL 0${i+1} / ${l[0].toUpperCase()}`;$('levelTitle').textContent=l[1];$('brief').textContent=l[2];$('noiseLabel').textContent='NOISE · '+['LOW','MEDIUM','HIGH','HIGH','VERY HIGH'][i];$('chiBadge').textContent=i>=3?'ACTIVE':'LEVEL 4';$('sgBadge').textContent=i>=4?'ACTIVE':'LEVEL 5';$('match').innerHTML='—<small> / 100</small>';$('chi').textContent='—';$('sg').textContent='—';$('result').hidden=true;renderLevels();draw()}
function draw(){const dpr=devicePixelRatio||1,w=canvas.clientWidth,h=220;canvas.width=w*dpr;canvas.height=h*dpr;ctx.scale(dpr,dpr);ctx.fillStyle='#101a1e';ctx.fillRect(0,0,w,h);const x=t=>20+t/DURATION*(w-40),y=f=>h-15-Math.log(Math.max(base*.65,f)/(base*.65))/Math.log(8)*(h-30);ctx.strokeStyle='#25373c';ctx.lineWidth=1;for(let i=0;i<7;i++){ctx.beginPath();ctx.moveTo(20+i*(w-40)/6,0);ctx.lineTo(20+i*(w-40)/6,h);ctx.stroke()}for(let i=0;i<5;i++){ctx.beginPath();ctx.moveTo(0,15+i*(h-30)/4);ctx.lineTo(w,15+i*(h-30)/4);ctx.stroke()}
if(view){for(const fr of view.frames){const max=Math.max(...fr.p,1e-8);for(let k=Math.floor(base*.65*1024/RATE);k<Math.min(fr.p.length,Math.ceil(base*5.2*1024/RATE));k++){const a=Math.max(0,(Math.log10(fr.p[k]/max+1e-7)+3)/3);if(a>.05){ctx.fillStyle=`rgba(91,202,207,${a*.65})`;ctx.fillRect(x(fr.t),y((k+1)*RATE/1024),Math.max(2,(w-40)/140),Math.max(2,y(k*RATE/1024)-y((k+1)*RATE/1024)))}}}ctx.strokeStyle='#79dbdb';ctx.lineWidth=1.7;ctx.beginPath();view.frames.forEach((f,i)=>{if(i===0)ctx.moveTo(x(f.t),y(f.peak));else ctx.lineTo(x(f.t),y(f.peak))});ctx.stroke()}
ctx.strokeStyle='#d6f489';ctx.lineWidth=2;ctx.setLineDash([5,5]);ctx.beginPath();for(let i=0;i<=120;i++){const t=DURATION*i/120;i?ctx.lineTo(x(t),y(frequency(t,base))):ctx.moveTo(x(t),y(frequency(t,base)))}ctx.stroke();ctx.setLineDash([]);ctx.font='9px sans-serif';ctx.fillStyle='#839c9f';ctx.fillText(`${base*4} Hz`,8,14);ctx.fillText(`${base} Hz`,8,h-4);if(capture){ctx.strokeStyle='#eaf7d3';ctx.beginPath();ctx.moveTo(x(progress),0);ctx.lineTo(x(progress),h);ctx.stroke()}}
function lock(on){busy=on;$('record').disabled=on;$('hear').disabled=on;$('demo').disabled=on;$('register').disabled=on;$('reset').disabled=on;$('stop').disabled=on;$('micOff').disabled=on;renderLevels()}
async function context(){ac??=new (window.AudioContext||window.webkitAudioContext)();await ac.resume();return ac}
async function enable(){if(!navigator.mediaDevices?.getUserMedia)throw new Error('Microphone access requires HTTPS or localhost and a supported browser.');const audio=await context();stream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:false,noiseSuppression:false,autoGainControl:false}});source=audio.createMediaStreamSource(stream);processor=audio.createScriptProcessor(2048,1,1);mute=audio.createGain();mute.gain.value=0;processor.onaudioprocess=e=>{if(capture)chunks.push(new Float32Array(e.inputBuffer.getChannelData(0)))};source.connect(processor);processor.connect(mute);mute.connect(audio.destination);$('record').textContent='◉   Record your chirp';$('micOff').hidden=false;stream.getAudioTracks()[0].onended=()=>{stream=null;$('record').textContent='◉   Enable microphone'};}
const wait=ms=>new Promise(r=>setTimeout(r,ms));
async function recordFor(seconds,live=false){chunks=[];capture=true;const start=performance.now();let lastCount=0;if(live)view={frames:[]};function animate(){progress=Math.min(DURATION,(performance.now()-start)/1000);if(live&&chunks.length){const latest=chunks[chunks.length-1];if(chunks.length!==lastCount){const p=spectrum(resample(latest,ac.sampleRate));let k=0;for(let j=Math.floor(base*.7*1024/RATE);j<Math.min(p.length,base*4.6*1024/RATE);j++)if(p[j]>p[k])k=j;view.frames.push({t:progress,p,peak:k*RATE/1024});lastCount=chunks.length}const peak=Math.max(...latest.map(Math.abs));$('timer').textContent=`${progress.toFixed(1)} / 2.4 s · INPUT ${peak>.98?'CLIPPING':peak>.005?'ACTIVE':'QUIET'}`;}draw();if(capture)raf=requestAnimationFrame(animate)}animate();await wait(seconds*1000);capture=false;cancelAnimationFrame(raf);const len=chunks.reduce((s,c)=>s+c.length,0),data=new Float32Array(len);let i=0;for(const c of chunks){data.set(c,i);i+=c.length}return resample(data,ac.sampleRate)}
function finish(result,demo=false){view=result;draw();$('match').innerHTML=`${result.match}<small> / 100</small>`;$('chi').textContent=result.chi.toFixed(2);$('sg').textContent=result.sg>999?'999+':result.sg.toFixed(2);const l=levels[level],passes=result.match>=l[4]&&(level<3||result.chi<3)&&(level<4||result.sg<6);$('result').hidden=false;$('resultTitle').textContent=(demo?'DEMO · ':'')+(passes?(level===4?'You found your signal.':'Signal found!'):'Keep searching.');let feedback=[];if(result.match<l[4])feedback.push(`Aim for ${l[4]}% match: start low and accelerate your pitch near the end.`);if(level>=3&&result.chi>=3)feedback.push('Keep a steady, smooth envelope throughout the chirp (χ² target < 3).');if(level>=4&&result.sg>=6)feedback.push('Excess high-frequency power: finish softly, without a pop or squeak (SG target < 6).');if(result.rms<.001&&!demo)feedback=['The microphone heard very little. Check the input device and move closer.'];$('resultText').textContent=feedback.join(' ')||(demo?'This generated chirp shows the target shape. Try it with your voice to unlock the next level.':'Your rising signal passed this level’s checks. '+(level===4?'All five missions complete. Try again in another register.':'Ready for the next challenge?'));$('next').hidden=!passes||demo||level===4;if(passes&&!demo){unlocked=Math.max(unlocked,Math.min(4,level+1));try{localStorage.setItem('chirplab-progress',unlocked)}catch{}renderLevels()}setStatus(demo?'Generated audio analysed locally. Demo runs do not unlock levels.':'Analysis complete. Audio was processed on your device and has been discarded.');$('scopeState').textContent='ANALYSIS COMPLETE';$('timer').textContent='2.4 SECOND CHIRP'}
$('record').onclick=async()=>{lock(true);try{if(!stream){await enable();setStatus('Microphone ready. Press Record your chirp. First, stay quiet for a one-second background measurement.');lock(false);return}view=null;$('result').hidden=true;setStatus('Stay quiet: measuring room noise for one second…');$('scopeState').textContent='MEASURING BACKGROUND';const bg=await recordFor(1);for(let n=3;n>=1;n--){setStatus(`Get ready… ${n}`);await wait(650)}setStatus('Chirp now! Start low, then sweep up.');$('scopeState').textContent='LISTENING';const data=await recordFor(DURATION,true);if(!stream)throw new Error('The microphone disconnected. Reconnect it and try again.');finish(analyze(data,bg,base,levels[level][3]));chunks=[]}catch(e){setStatus(e.name==='NotAllowedError'?'Microphone permission was denied. Allow it in your browser settings, or try the demo.':e.name==='NotFoundError'?'No microphone found. Connect a microphone, or try the demo.':e.message);$('scopeState').textContent='READY TO LISTEN'}finally{capture=false;chunks=[];lock(false)}};
$('hear').onclick=async()=>{lock(true);try{const audio=await context(),data=synth(base),buffer=audio.createBuffer(1,data.length,RATE);buffer.copyToChannel(data,0);const player=audio.createBufferSource(),gain=audio.createGain();gain.gain.value=.5;player.buffer=buffer;player.connect(gain);gain.connect(audio.destination);playing=true;setStatus('Listen for the accelerating rise. Playback ends before recording starts.');player.start();await new Promise(r=>player.onended=r);playing=false;setStatus('Your turn: hum or whistle the same rising shape.')}catch(e){setStatus('Playback unavailable: '+e.message)}finally{lock(false)}};
$('demo').onclick=()=>{lock(true);try{const rng=random(11),bg=Float32Array.from({length:RATE},()=>rng()*.003);finish(analyze(synth(base),bg,base,levels[level][3]),true)}finally{lock(false)}};
$('next').onclick=()=>selectLevel(Math.min(4,level+1));$('register').onchange=()=>{base=Number($('register').value);selectLevel(level)};$('scienceBtn').onclick=()=>{$('science').open=true;$('science').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'})};$('reset').onclick=()=>{unlocked=0;try{localStorage.removeItem('chirplab-progress')}catch{}selectLevel(0);setStatus('Progress reset. Start a new mission.')};
function stopMic(){capture=false;stream?.getTracks().forEach(t=>t.stop());stream=null;$('micOff').hidden=true;processor?.disconnect();source?.disconnect();mute?.disconnect();processor=null;source=null;$('record').textContent='◉   Enable microphone';setStatus('Microphone off. You can enable it again at any time.')}$('stop').onclick=stopMic;$('micOff').onclick=stopMic;window.addEventListener('pagehide',()=>{stopMic();ac?.close()});window.addEventListener('resize',draw);selectLevel(0);
